/* O compilador le de cima para baixo.

   ordemInvertida chama triplo — e triplo esta definida LA EMBAIXO.
   Como esta, o arquivo NAO compila: na linha da chamada o nome triplo
   ainda nao foi apresentado.

   Nao mude a ordem das caixas: acrescente o cartaz. */

/* 1. escreva AQUI o prototipo de triplo — a primeira linha dela, com ; no fim */

int ordemInvertida(int lado) {
    return triplo(lado);
}

int triplo(int n) {
    return n * 3;
}

