#include <stdio.h>

/* teste do desafio ordem-invertida — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Fase VALOR: o teste declara os PROTOTIPOS das caixas do aluno e compara o
   VALOR DEVOLVIDO. Repare que o teste faz, para as caixas do aluno, o mesmo
   que o cartaz que falta no arquivo dele: apresenta o nome antes de usar. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int ordemInvertida(int lado);
int triplo(int n);

SM_TEST(o_perimetro_do_lado_4_e_12) {
    checa_int("o perimetro do lado 4 e 12", ordemInvertida(4), 12,
              "ordemInvertida chama triplo: 4 x 3 = 12");
}

SM_TEST(o_perimetro_do_lado_7_e_21) {
    checa_int("o perimetro do lado 7 e 21", ordemInvertida(7), 21,
              "com outro lado o valor muda: 7 x 3 = 21");
}

SM_TEST(a_caixa_de_baixo_responde) {
    checa_int("o triplo de 5 e 15", triplo(5), 15,
              "a caixa definida embaixo continua valendo — o cartaz so a apresentou mais cedo");
}

solutionCode:
/* O cartaz na porta: o prototipo de triplo apresenta o nome ao compilador
   antes da primeira chamada. A definicao continua la embaixo. */
int triplo(int n);

int ordemInvertida(int lado) {
    return triplo(lado);
}

int triplo(int n) {
    return n * 3;
}
